import * as React from 'react';
import { inputBaseStyles } from '@/components/input';
import { clx } from '@/utils/clx';

/**
 * This component is based on the `textarea` element and supports all of its props
 */
const Textarea = React.forwardRef<HTMLTextAreaElement, React.ComponentPropsWithoutRef<'textarea'>>(({ className, ...props }, ref) => (
  <textarea ref={ref} className={clx(inputBaseStyles, 'txt-small min-h-[60px] w-full px-2 py-1.5', className)} {...props} />
));
Textarea.displayName = 'Textarea';

export { Textarea };
